bio("umar-ibn-abdulaziz", [
 ("هُوَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ بْنِ مَرْوَانَ، أَمِيرُ الْمُؤْمِنِينَ، أَبُو حَفْصٍ الْأُمَوِيُّ.", "Er ist ʿUmar ibn ʿAbd al-ʿAziz ibn Marwan, der Befehlshaber der Gläubigen, Abu Hafs aus dem Haus Umayya.", 3886),
 ("كَانَ إِمَامًا عَالِمًا زَاهِدًا عَابِدًا.", "Er war ein gelehrter Imam, ein Asket und ein Mann der Anbetung.", 3886),
 ("صَلَّى بِأَنَسِ بْنِ مَالِكٍ، فَقَالَ أَنَسٌ: مَا رَأَيْتُ أَحَدًا أَشْبَهَ صَلَاةً بِرَسُولِ اللَّهِ ﷺ مِنْ هَذَا الْفَتَى.", "Er leitete Anas ibn Malik im Gebet, und Anas sagte: Ich habe niemanden gesehen, dessen Gebet dem des Gesandten Allahs ﷺ ähnlicher war als das dieses jungen Mannes.", 3886),
 ("وَكَانَ حَرِيصًا عَلَى الْعَدْلِ، زَاهِدًا مَعَ الْخِلَافَةِ.", "Er bemühte sich um Gerechtigkeit mit allen Mitteln und lebte asketisch, obwohl er Kalif war.", 3892),
 ("وَقَالَ: لَوْ أَقَمْتُ فِيكُمْ خَمْسِينَ عَامًا مَا اسْتَكْمَلْتُ فِيكُمُ الْعَدْلَ.", "Er sagte: Selbst wenn ich fünfzig Jahre unter euch bliebe, könnte ich die Gerechtigkeit unter euch nicht vollenden.", 3901),
 ("تُوُفِّيَ فِي رَجَبٍ سَنَةَ إِحْدَى وَمِئَةٍ، بِدَيْرِ سَمْعَانَ مِنْ أَرْضِ حِمْصَ.", "Er starb im Radschab des Jahres 101 in Dair Simʿan bei Homs.", 3916),
], [
 ("athar", "مَا رَأَيْتُ أَحَدًا أَشْبَهَ صَلاَةً بِرَسُوْلِ اللهِ -ﷺ- مِنْ هَذَا الفَتَى", "Ich habe niemanden gesehen, dessen Gebet dem des Gesandten Allahs ﷺ ähnlicher war als das dieses jungen Mannes. (Anas ibn Malik)", 3886, E),
 ("athar", "حَرِيْصًا عَلَى العَدْلِ بِكُلِّ مُمْكِنٍ، وَافِرَ العِلْمِ، فَقِيْهَ النَّفْسِ", "… bemüht um Gerechtigkeit mit allen Mitteln, reich an Wissen, von tiefem Verständnis. (adh-Dhahabi)", 3892),
])
bio("ibn-sirin", [
 ("هُوَ مُحَمَّدُ بْنُ سِيرِينَ، أَبُو بَكْرٍ الْبَصْرِيُّ، مَوْلَى أَنَسِ بْنِ مَالِكٍ.", "Er ist Muhammad ibn Sirin, Abu Bakr aus Basra, ein Schutzbefohlener (Maula) des Anas ibn Malik.", 3759),
 ("وُلِدَ قَبْلَ نِهَايَةِ خِلَافَةِ عُمَرَ بِسَنَتَيْنِ.", "Er wurde zwei Jahre vor dem Ende von ʿUmars Kalifat geboren.", 3759),
 ("سَمِعَ أَبَا هُرَيْرَةَ وَابْنَ عَبَّاسٍ وَابْنَ عُمَرَ وَأَنَسًا وَغَيْرَهُمْ.", "Er hörte Abu Hurayra, Ibn ʿAbbas, Ibn ʿUmar, Anas und andere.", 3759),
 ("وَكَانَ مَشْهُورًا بِالْوَرَعِ، حَتَّى قِيلَ: لَمْ يَكُنْ لِأَحَدٍ مِثْلُ وَرَعِهِ.", "Er war für seine Gewissenhaftigkeit (Waraʿ) berühmt; man sagte, niemand habe eine Gewissenhaftigkeit wie er gehabt.", 3763),
 ("وَقَالَ: إِنَّ هَذَا الْعِلْمَ دِينٌ، فَانْظُرُوا عَمَّنْ تَأْخُذُونَ دِينَكُمْ.", "Er sagte: Dieses Wissen ist Religion – also seht genau hin, von wem ihr eure Religion nehmt.", 3764),
 ("وَمَاتَ وَهُوَ ابْنُ ثَمَانٍ وَسَبْعِينَ سَنَةً.", "Er starb im Alter von 78 Jahren.", 3760),
], [
 ("athar", "مَا رَأَيْتُ أَحَدًا أَفْقَهَ فِي وَرَعِهِ، وَلاَ أَوْرَعَ فِي فَقْهِهِ مِنْ مُحَمَّدِ بنِ سِيْرِيْنَ", "Ich habe niemanden gesehen, der in seiner Gewissenhaftigkeit verständiger und in seinem Verständnis gewissenhafter war als Muhammad ibn Sirin.", 3762, E),
])
bio("ata", [
 ("هُوَ عَطَاءُ بْنُ أَبِي رَبَاحٍ، أَبُو مُحَمَّدٍ، مُفْتِي الْحَرَمِ.", "Er ist ʿAtaʾ ibn Abi Rabah, Abu Muhammad, der Rechtsgelehrte des heiligen Bezirks (Mekka).", 3850),
 ("وُلِدَ فِي خِلَافَةِ عُثْمَانَ، وَنَشَأَ بِمَكَّةَ.", "Er wurde während des Kalifats von ʿUthman geboren und wuchs in Mekka auf.", 3851),
 ("كَانَ الْمُنَادِي فِي الْحَجِّ يَقُولُ: لَا يُفْتِي النَّاسَ إِلَّا عَطَاءُ بْنُ أَبِي رَبَاحٍ.", "Beim Haddsch rief ein Ausrufer: Niemand außer ʿAtaʾ ibn Abi Rabah soll den Leuten Rechtsauskunft geben.", 3854),
 ("وَحَجَّ أَكْثَرَ مِنْ سَبْعِينَ حَجَّةً.", "Er vollzog mehr als siebzig Mal den Haddsch.", 3854),
 ("وَكَانَ الْمَسْجِدُ فِرَاشَهُ عِشْرِينَ سَنَةً، وَكَانَ مِنْ أَحْسَنِ النَّاسِ صَلَاةً.", "Zwanzig Jahre lang war die Moschee sein Lager, und er gehörte zu den Menschen mit dem schönsten Gebet.", 3856),
 ("وَمَاتَ وَهُوَ أَرْضَى أَهْلِ الْأَرْضِ عِنْدَ النَّاسِ.", "Als er starb, war er bei den Menschen der Beliebteste auf der Erde.", 3856),
], [
 ("athar", "لاَ يُفْتِي النَّاسَ إِلاَّ عَطَاءُ بنُ أَبِي رَبَاحٍ", "Niemand außer ʿAtaʾ ibn Abi Rabah soll den Leuten Rechtsauskunft geben.", 3854, E),
 ("athar", "كَانَ المَسْجِدُ فِرَاشَ عَطَاءٍ عِشْرِيْنَ سَنَةً، وَكَانَ مِنْ أَحْسَنِ النَّاسِ صَلاَةً", "Zwanzig Jahre war die Moschee ʿAtaʾs Lager, und er hatte eines der schönsten Gebete. (Ibn Dschuraidsch)", 3856, E),
])
bio("urwa", [
 ("هُوَ عُرْوَةُ بْنُ الزُّبَيْرِ بْنِ الْعَوَّامِ، أَبُو عَبْدِ اللَّهِ.", "Er ist ʿUrwa ibn az-Zubayr ibn al-ʿAwwam, Abu ʿAbdillah.", 3574),
 ("كَانَ عَالِمَ الْمَدِينَةِ، وَأَحَدَ الْفُقَهَاءِ السَّبْعَةِ.", "Er war der Gelehrte Medinas und einer der sieben Rechtsgelehrten.", 3574),
 ("وَأَخَذَ عِلْمًا كَثِيرًا عَنْ خَالَتِهِ عَائِشَةَ.", "Er lernte viel Wissen von seiner Tante ʿAischa.", 3577),
 ("وَكَانَ يَقُولُ لِلشَّبَابِ: تَعَلَّمُوا، فَإِنَّكُمْ تَكُونُونَ كِبَارَ قَوْمٍ.", "Er sagte zu den jungen Leuten: Lernt! Denn bald werdet ihr die Großen eures Volkes sein.", 3577),
 ("وَكَانَ يَقْرَأُ رُبُعَ الْقُرْآنِ كُلَّ يَوْمٍ، وَيَقُومُ بِهِ اللَّيْلَ.", "Er las jeden Tag ein Viertel des Quran und betete damit in der Nacht.", 3579),
 ("وَأَصَابَتْ رِجْلَهُ الْآكِلَةُ فَقُطِعَتْ، فَصَبَرَ.", "Sein Bein wurde vom Brand befallen und abgenommen, und er blieb geduldig.", 3579),
], [
 ("athar", "عَالِمُ المَدِيْنَةِ، أَبُو عَبْدِ اللهِ القُرَشِيُّ، الأَسَدِيُّ، المَدَنِيُّ، الفَقِيْهُ، أَحَدُ الفُقَهَاءِ السَّبْعَةِ", "Der Gelehrte Medinas, Abu ʿAbdillah …, der Rechtsgelehrte, einer der sieben Rechtsgelehrten. (adh-Dhahabi)", 3574),
 ("athar", "كَانَ عُرْوَةُ يَقْرَأُ رُبُعَ القُرْآنِ كُلَّ يَوْمٍ فِي المُصْحَفِ نَظَرًا، وَيَقُوْمُ بِهِ اللَّيْلَ", "ʿUrwa las jeden Tag ein Viertel des Quran aus dem Mushaf und betete damit in der Nacht.", 3579, E),
])
